#include<math.h>
#include<string>
using namespace std;
#include<algorithm>
#include<stdlib.h>
int closest_integer(string value){
    float f = stof(value);
	int intf = (int)f;
	int diff_neg = abs(intf - f);
	int diff_pos = (int)f + 1 - f;
	if (diff_neg <= diff_pos)
		return intf;
	else
		return intf + 1;
}

