#include<stdlib.h>
int closest_integer(string value){
    int len = value.length();
  int i = 0;
  int l = 0;
  while(i < len) {
    if(value[i] == '.') {
      l = len - i - 1;
      break;
    }
    i++;
  }
  long v = std::stol(value.substr(0, i));
  long p = std::stol(value.substr(i + 1, l));
  long x = pow(10, l - 1);
  if(p >= x / 2) {
    v++;
  }
  return v;
}

