int closest_integer(string value){
    int counter = 0;
  int digit = 0;
  std::string ret = "";
  std::string ret2 = "";
  if (value[0] == '-') {
    counter = 1;
  }
  while (value[counter] != '.') {
    ret += value[counter];
    counter++;
  }
  // return ret;
  if (ret.length() == 1) {
    digit = stoi(ret);
    if (digit < 9) {
      digit++;
    }
    return digit;
  }
  for (int i = 0; i < ret.length(); i++) {
    if (ret[i] == '0') {
      ret2 += ret[i];
    }
    else if (ret[i] != '0') {
      ret2 += ret[i];
      break;
    }
  }
  if (ret2.length() == 1) {
    digit = stoi(ret2);
    if (digit < 9) {
      digit++;
    }
    return digit;
  }
  if (value[0] == '-') {
    digit = stoi(ret2);
    if (digit > -9) {
      digit--;
    }
    return digit;
  }
  digit = stoi(ret2);
  if (digit < 9) {
    digit++;
  }
  return digit;
}

