int closest_integer(string value){
    std::string str;
  int i = 0;
  int flag = 0;
  int decimal_count = 0;
  for(char c : value) {
    if(c == '.') {
      flag = 1;
      decimal_count++;
    }
    if(decimal_count > 1) {
      return -1;
    }
    if(flag && c == '.') {
      break;
    }
    if(flag) {
      str += c;
    }
    i++;
  }
  if(str.size() == 0) {
    return atoi(value.c_str());
  }
  if(str.size() > 2) {
    return -1;
  }
  i--;
  long decimal_part = atoi(str.c_str());
  long integer_part = atoi(value.substr(0, i).c_str());
  if(decimal_part >= 50) {
    return integer_part + 1;
  }
  else {
    return integer_part;
  }
}

