#include<stdio.h>
#include<string>
using namespace std;
#include<algorithm>
#include<math.h>
#include<stdlib.h>
string fix_spaces(string text){
    std::vector<char> text_in_chars{};
  for (const auto &char_ : text) {
    text_in_chars.push_back(char_);
  }
  for (auto &char_ : text_in_chars) {
    if (char_ == ' ') {
      char_ = '_';
    }
  }
  std::vector<int> count_spaces_in_row{};
  int count_spaces = 0;
  for (int i = 0; i < text_in_chars.size(); ++i) {
    if (text_in_chars[i] == '_') {
      count_spaces++;
    } else {
      count_spaces_in_row.push_back(count_spaces);
      count_spaces = 0;
    }
  }
  std::vector<int> indexes_for_replacement{};
  for (int i = 0; i < count_spaces_in_row.size(); ++i) {
    if (count_spaces_in_row[i] > 2) {
      indexes_for_replacement.push_back(i);
    }
  }
  for (const auto &index : indexes_for_replacement) {
    text_in_chars[index] = '-';
  }
  std::string result{};
  for (const auto &char_ : text_in_chars) {
    result += char_;
  }
  return result;
}

