string fix_spaces(string text){
    int length = text.length();
  std::string new_text = "";
  for (int i = 0; i < length; i++) {
    // We are not at the start of the string,
    // and the current character is a space and the 
    // previous character is a space, then we 
    // add a - to the new string
    if (i > 0 && text[i] == ' ' && text[i - 1] == ' ') {
      new_text += '-';
    }
    // We are not at the start of the string,
    // and the current character is a space and the 
    // previous character is not a space, then we 
    // add a _ to the new string
    else if (i > 0 && text[i] == ' ' && text[i - 1] != ' ') {
      new_text += '_';
    }
    // Otherwise we add the original character 
    // to the new string
    else {
      new_text += text[i];
    }
  }
  return new_text;
}

