    int upper_case{0};
    int lower_case{0};
    for (const auto& c : extension) {
      if (isupper(c)) {
        ++upper_case;
      } else {
        ++lower_case;
      }
    }
    double strength{static_cast<double>(upper_case - lower_case)};
