vector<vector<int>> get_row(vector<vector<int>> lst, int x){
    std::vector<std::tuple<long, long>> result;
    if(lst.size() == 0) return result;
    for(long i = 0; i < lst.size(); i++) {
        for(long j = 0; j < lst[i].size(); j++) {
            if(lst[i][j] == x) {
                result.push_back(std::make_tuple(i, j));
            }
        }
    }
    std::sort(result.begin(), result.end(), [](const std::tuple<long, long>& lhs, const std::tuple<long, long>& rhs) {
        return std::get<0>(lhs) < std::get<0>(rhs);
    });
    long start = 0;
    long end = 0;
    while(start < result.size()) {
        end = start;
        while(end < result.size() && std::get<0>(result[start]) == std::get<0>(result[end])) {
            end++;
        }
        std::sort(result.begin() + start, result.begin() + end, [](const std::tuple<long, long>& lhs, const std::tuple<long, long>& rhs) {
            return std::get<1>(lhs) > std::get<1>(rhs);
        });
        start = end;
    }
    return result;
}

