vector<vector<int>> get_row(vector<vector<int>> lst, int x){
    std::vector<std::tuple<long, long>> final_vector;
    for (int i = 0; i < lst.size(); i++) {
        auto current_vector = lst[i];
        std::vector<long> current_vector_index;
        for (int j = 0; j < current_vector.size(); j++) {
            if (current_vector[j] == x) {
                current_vector_index.push_back(j);
            }
        }
        for (int k = 0; k < current_vector_index.size(); k++) {
            std::tuple<long, long> current_tuple = std::make_tuple(i, current_vector_index[k]);
            final_vector.push_back(current_tuple);
        }
    }
    std::sort(final_vector.begin(), final_vector.end(), [](std::tuple<long, long> left, std::tuple<long, long> right) {
        long first_left = std::get<0>(left);
        long first_right = std::get<0>(right);
        long second_left = std::get<1>(left);
        long second_right = std::get<1>(right);
        if (first_left != first_right) {
            return first_left < first_right;
        } else {
            return second_left > second_right;
        }
    });
    return final_vector;
}

