            }
            heights[i][j] = water;
        }
    }
    for(int j = 0; j < cols; j++) {
        long water = 0;
        for(int i = rows - 1; i >= 0; i--) {
            if(grid[i][j] == 1) {
                water++;
            } else {
                water = 0;
            }
            heights[i][j] = std::min(heights[i][j], water);
        }
    }
    long max = 0;
    for(int i = 0; i < rows; i++) {
        for(int j = 0; j < cols; j++) {
            if(heights[i][j] > max) {
                max = heights[i][j];
            }
        }
    }
    long count = 0;
    for(int i = 0; i < rows; i++) {
        for(int j = 0; j < cols; j++) {
            if(heights[i][j] == max) {
                count++;
            }
        }
    }
