        long top = cells.top();
        cells.pop();
        long fill = std::min(top, capacity);
        if (fill > 0) {
            total_fill += fill;
        }
        if (top > capacity) {
            top -= capacity;
            cells.push(top);
        }
    }
    return total_fill;
}

