int max_fill(vector<vector<int>> grid,int capacity){
    long rows = grid.size();
    long cols = grid[0].size();
    std::priority_queue<long> pq;
    for(long row = 0; row < rows; row++) {
        for(long col = 0; col < cols; col++) {
            if(grid[row][col] == 1) {
                pq.push(col);
            }
        }
    }
    long total_time = 0;
    long curr_fill = 0;
    while(!pq.empty()) {
        long r_start = -1;
        long r_end = -1;
        for(long row = 0; row < rows; row++) {
            if(r_start == -1 && grid[row][pq.top()] == 1) {
                r_start = row;
            }
            if(r_start != -1 && grid[row][pq.top()] == 1) {
                r_end = row;
            }
        }
        if(r_start == r_end) {
            curr_fill += capacity;
            total_time += 1;
        } else {
            long runs = (r_end - r_start) / capacity;
            long last_run = (r_end - r_start) % capacity;
            total_time += runs + 1;
            curr_fill += last_run;
        }
        long col = pq.top();
        pq.pop();
        for(long row = 0; row < rows; row++) {
            if(grid[row][col] == 1) {
                grid[row][col] = 0;
            }
        }
    }
    return total_time;
}

