int max_fill(vector<vector<int>> grid,int capacity){
    // we sort wells by their height
  long rows = grid.size();
  long cols = grid[0].size();
  std::vector<std::pair<long, long>> wells;
  for (long i = 0; i < rows; i++) {
    long height = 0;
    for (long j = 0; j < cols; j++) {
      height += grid[i][j];
    }
    wells.push_back(std::make_pair(height, i));
  }
  std::sort(wells.begin(), wells.end());
  long count = 0;
  for (auto w : wells) {
    // for the ith well, we fill it with capacity water in each bucket
    // and then empty it by putting the water into the remaining wells
    long i = w.second;
    long num_buckets = capacity;
    while (num_buckets-- > 0) {
      // fill ith well
      long j = 0;
      while (grid[i][j] != 0) {
        count++;
        grid[i][j]--;
        j++;
      }
      // empty ith well
      for (long k = 0; k < rows; k++) {
        if (i == k) {
          continue;
        }
        while (j < cols && grid[k][j] != 0) {
          count++;
          grid[k][j]--;
          j++;
        }
      }
    }
  }
  return count;
}

