    std::vector<long> heights(col, 0);
    for(long r = 0; r < row; r++) {
        for(long c = 0; c < col; c++) {
            if(grid[r][c] == 1) {
                heights[c] = 1;
            }
        }
    }
    long empty_col = 0;
    for(long c = 0; c < col; c++) {
        if(heights[c] == 0) {
            empty_col++;
        }
    }
    if(empty_col == col) {
        return 0;
    }
    std::sort(heights.begin(), heights.end());
    long ans = 0;
    for(long h = 0; h < row; h++) {
        long pass = 0;
        for(long c = 0; c < col; c++) {
            if(h < heights[c]) {
                ans++;
                pass++;
            }
        }
        if(pass == capacity) {
            break;
        }
    }
    return ans;
}

