    factors.push_back(1);
    for (int i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) {
            factors.push_back(i);
            if (i != sqrt(n)) {
                factors.push_back(n / i);
            }
        }
    }
    std::sort(factors.begin(), factors.end());
