#include<math.h>
#include<vector>
using namespace std;
#include<algorithm>
#include<stdlib.h>
vector<int> factorize(int n){
    std::vector<long> factors;
    std::map<long, int> factors_map;
    while (n % 2 == 0) {
        factors_map[2]++;
        n = n / 2;
    }
    for (long i = 3; i <= sqrt(n); i = i + 2) {
        while (n % i == 0) {
            factors_map[i]++;
            n = n / i;
        }
    }
    if (n > 2) {
        factors_map[n]++;
    }
    for (auto factor : factors_map) {
        for (int i = 0; i < factor.second; i++) {
            factors.push_back(factor.first);
        }
    }
    return factors;
}

