        return true;
    }
    // check if brackets string has odd number of characters. If yes, return false
    if (brackets.length() % 2 != 0) {
        return false;
    }
    // if brackets has even number of characters and is not empty, create a stack
    std::stack<char> stk;
    // iterate through brackets string
    for (char &c : brackets) {
        // if current character is opening bracket, push it to stack
        if (c == '<') {
            stk.push(c);
        }
        // if current character is closing bracket
        else {
            // if stack is empty, that means there's a closing bracket with no
            // corresponding opening bracket, so return false
            if (stk.empty()) {
                return false;
            }
            // otherwise, pop the stack as there's an opening bracket corresponding
            // to the current closing bracket
            else {
                stk.pop();
            }
        }
    }
    // if stack is empty, return true. Otherwise, return false
    return stk.empty();
}

