int x_or_y(int n,int x,int y){
    if (n <= 1) return y;
    int s = 0;
    long u = n - 1;
    while (u % 2 == 0) {
        s++;
        u /= 2;
    }
    // u is now odd
    int t = 1;
    long v = 2;
    while (v <= u) {
        t *= v;
        v++;
    }
    long r = t + s;
    while (r % 2 == 0) r /= 2;
