vector<string> sorted_list_sum(vector<string> lst){
    std::vector<std::string> result;
    for (auto v : lst) {
        result.push_back(v);
    }
    for (int i = 0; i < lst.size(); i++) {
        for (int j = i + 1; j < lst.size(); j++) {
            if (lst[i].length() > lst[j].length()) {
                std::swap(result[i], result[j]);
            }
        }
    }
    return result;
}

