    int count = 0;
    int sublen = substring.length();
    int strlen = string.length();
    if(sublen==0 || strlen==0) return 0;
    for(int i=0;i<strlen;i++){
        if(string[i]==substring[0]){
            if(sublen==1) count++;
            else{
                for(int j=1;j<sublen;j++){
                    if(string[i+j]==substring[j]){
                        if(j==sublen-1) count++;
                    }
                    else{
                        break;
                    }
                }
            }
        }
    }
    return count;
}

