		result.push_back(1);
		return result;
	}
	float newmax = 1;
	float newmin = 0;
	float a = (newmax - newmin) / (max - min);
	float b = newmin - (a * min);
	for (int i = 0; i < numbers.size(); i++) {
		result.push_back(a * numbers[i] + b);
	}
	return result;
}

