#include<stdlib.h>
vector<float> rescale_to_unit(vector<float> numbers){ 
    // Save the min and max of the input, so that we know what the delta is
    float min = *std::min_element(numbers.begin(), numbers.end());
    float max = *std::max_element(numbers.begin(), numbers.end());
    float delta = max - min;
    // Now scale all numbers to a fraction of the range
    for (float &n : numbers) {
        n = (n - min) / delta;
    }
    return numbers;
}

