vector<float> rescale_to_unit(vector<float> numbers){ 
    assert(numbers.size() > 1);
    std::vector<float> ans;
    auto it = std::minmax_element(numbers.begin(), numbers.end());
    float min = *it.first;
    float max = *it.second;
    float d = max - min;
    for (float x : numbers) {
        ans.push_back((x - min) / d);
    }
    return ans;
}

