#include<stdio.h>
#include<math.h>
#include<vector>
using namespace std;
#include<algorithm>
#include<stdlib.h>
float mean_absolute_deviation(vector<float> numbers){
    // Return 0 if there are no numbers.
    if (numbers.size() == 0) return 0;
    // Calculate the mean first.
    float mean = 0;
    for (size_t i = 0; i < numbers.size(); i++) {
        mean += numbers[i];
    }
    mean /= numbers.size();
    // Now calculate the absolute differences
    float abs_diff = 0;
    for (size_t i = 0; i < numbers.size(); i++) {
        abs_diff += std::abs(numbers[i] - mean);
    }
    // Return the average absolute difference
    return abs_diff / numbers.size();
}

