float mean_absolute_deviation(vector<float> numbers){
    // Find mean:
    float sum = 0.0;
    for (int i = 0; i < numbers.size(); i++) {
        sum += numbers[i];
    }
    float mean = sum / numbers.size();
    // Find absolute difference between each element and mean:
    std::vector<float> abs_diff;
    for (int i = 0; i < numbers.size(); i++) {
        abs_diff.push_back(std::abs(numbers[i] - mean));
    }
    // Find average of absolute differences:
    float sum_abs_diff = 0.0;
    for (int i = 0; i < abs_diff.size(); i++) {
        sum_abs_diff += abs_diff[i];
    }
    float mean_abs_diff = sum_abs_diff / abs_diff.size();
    return mean_abs_diff;
}

