#include<stdlib.h>
float mean_absolute_deviation(vector<float> numbers){
    // Compute the mean of the dataset as a float
    float mean=0;
    float x=0;
    int n=numbers.size();
    for(int i=0;i<n;i++)
    {
        x=x+numbers[i];
    }
    mean=x/n;
    // Compute the absolute difference from the mean, then take the mean of that
    std::vector<float> ab;
    for(int i=0;i<n;i++)
    {
        ab.push_back(abs(numbers[i]-mean));
    }
    float y=0;
    for(int i=0;i<n;i++)
    {
        y=y+ab[i];
    }
    float mad=y/n;
    return mad;
}

