bool valid_date(string date){
    bool res = true;
	int month = 0, day = 0, year = 0;
	int count = 0;
	for (size_t i = 0; i < date.size(); i++) {
		if (date[i] == '-')
			count++;
	}
	if (count != 2)
		return false;
	size_t pos = date.find('-');
	if (pos != 2)
		return false;
	std::stringstream ss;
	ss << date.substr(0, 2);
	ss >> month;
	ss.clear();
	size_t pos2 = date.find('-', pos + 1);
	ss << date.substr(pos + 1, pos2 - pos - 1);
	ss >> day;
	ss.clear();
	ss << date.substr(pos2 + 1, date.size() - pos2 - 1);
	ss >> year;
	ss.clear();
	if (month < 1 || month > 12)
		return false;
	switch (month) {
	case 1:
	case 3:
	case 5:
	case 7:
	case 8:
	case 10:
	case 12:
		if (day < 1 || day > 31)
			return false;
		break;
	case 4:
	case 6:
	case 9:
	case 11:
		if (day < 1 || day > 30)
			return false;
		break;
	case 2:
		if (day < 1 || day > 29)
			return false;
		break;
	}
	return res;
}

