    if (l.size() <= 2) {
        return true;
    }
    bool is_increasing = l[0] < l[1];
    for (int i = 1; i < l.size() - 1; i++) {
        if (is_increasing) {
            if (l[i] > l[i + 1]) {
                return false;
            }
        } else {
            if (l[i] < l[i + 1]) {
                return false;
            }
        }
