string int_to_mini_romank(int number){
    std::string result;
  int digitCount=0;
  while(number>0){
    int digit=number%10;
    number/=10;
    switch(digitCount){
      case 0:
        if(digit==4){
          result.insert(0,"iv");
        }else if(digit==9){
          result.insert(0,"ix");
        }else{
          int i=0;
          while(i<digit){
            if(i==5){
              result.insert(0,"v");
            }else{
              result.insert(0,"i");
            }
            i++;
          }
        }
        break;
      case 1:
        if(digit==4){
          result.insert(0,"xl");
        }else if(digit==9){
          result.insert(0,"xc");
        }else{
          int i=0;
          while(i<digit){
            if(i==5){
              result.insert(0,"l");
            }else{
              result.insert(0,"x");
            }
            i++;
          }
        }
        break;
      case 2:
        if(digit==4){
          result.insert(0,"cd");
        }else if(digit==9){
          result.insert(0,"cm");
        }else{
          int i=0;
          while(i<digit){
            if(i==5){
              result.insert(0,"d");
            }else{
              result.insert(0,"c");
            }
            i++;
          }
        }
        break;
      case 3:
        int i=0;
        while(i<digit){
          result.insert(0,"m");
          i++;
        }
        break;
    }
    digitCount++;
  }
  return result;
}

