    // Create a stack to hold characters
	std::stack<char> brackets;
	int countOpen = 0;
	int countClose = 0;
	for (char const& c : string) {
		// if the stack is empty, push the current character to the stack
		if (brackets.empty()) {
			brackets.push(c);
			// if the stack is not empty, and the current character is the same as the top of the stack
			// pop the top off of the stack
		} else if (c == brackets.top()) {
			brackets.pop();
			// otherwise push the current character to the stack
		} else {
			brackets.push(c);
		}
	}
	// if the stack is empty, the string is nested
	if (brackets.empty()) {
		return true;
	}
	return false;
}

