        if (curr_index % 2 != 0) {
            l_prime.push_back(l[curr_index]);
        }
        // If the index is even, we store the value at that index in the even_index variable.
        else {
            even_index = curr_index;
        }
        // We then increment curr_index by 1.
        curr_index++;
    }
    // We then sort the even indices of l.
    std::sort(l.begin(), l.begin() + even_index + 1);
    // We then loop through the entire input vector.
    curr_index = 0;
    while (curr_index < l.size()) {
        // If the index is even, we add the value at that index to l_prime.
        if (curr_index % 2 == 0) {
            l_prime.push_back(l[curr_index]);
