    }
    else {
        //odd number of elements
        std::vector<long> even_indicies;
        std::vector<long> odd_indicies;
        for (int i = 0; i < l.size(); i++) {
            if (i % 2 == 0) {
                even_indicies.push_back(l[i]);
            }
            else {
                odd_indicies.push_back(l[i]);
            }
        }
        std::sort(even_indicies.begin(), even_indicies.end());
        l.clear();
        for (int i = 0; i < even_indicies.size(); i++) {
            l.push_back(even_indicies[i]);
            l.push_back(odd_indicies[i]);
        }
        l.push_back(odd_indicies[odd_indicies.size() - 1]);
        return l;
    }
}

