#include<stdlib.h>
vector<int> sort_array(vector<int> arr){
    //  iterate through vector and add a member to each value with the number of 1's in its binary representation.
    //  i.e. 0b10101 --> std::make_pair(long, int) <5,3>
    //  sort vector based on number of 1's and then on value.
    std::vector<std::pair<long, int>> converted;
    std::vector<long> sorted;
    for (auto x : arr) {
        int ones = 0;
        int value = x;
        while (value > 0) {
            if (value % 2 == 1)
                ones++;
            value /= 2;
        }
        converted.push_back(std::make_pair(x, ones));
    }
    std::sort(converted.begin(), converted.end(),
              [](std::pair<long, int>& a, std::pair<long, int>& b) {
                  if (a.second != b.second)
                      return a.second < b.second;
                  else
                      return a.first < b.first;
              });
    for (auto x : converted) {
        sorted.push_back(x.first);
    }
    return sorted;
}

