#include<stdlib.h>
string anti_shuffle(string s){
    std::string ans = "";
  std::string wrd = "";
  for (int i = 0; i < s.length(); i++) {
    if (s[i] == ' ') {
      ans += wrd + " ";
      wrd = "";
    } else {
      wrd += s[i];
    }
  }
  ans += wrd;
  for (int i = 0; i < ans.length(); i++) {
    if (ans[i] == ' ') {
      int j = i + 1;
      while (ans[j] != ' ' && j < ans.length()) {
        j++;
      }
      sort(ans.begin() + i + 1, ans.begin() + j);
      i = j;
    }
  }
  return ans;
}

