        if(game[i] == guess[i]){
            game[i] = 0;
        }
        else if(game[i] > guess[i]){
            count = game[i] - guess[i];
            game[i] = count;
        }
        else if(game[i] < guess[i]){
            count = guess[i] - game[i];
            game[i] = count;
        }
    }
    return game;
}

