      j--;
    if (i < j) {
      int temp = result[i];
      result[i] = result[j];
      result[j] = temp;
    }
  }
  if (isOdd)
    std::sort(result.begin(), result.end());
  else
    std::sort(result.begin(), result.end(), std::greater<long>());
  return result;
}

