    }
    int dist = j - i;
    bool prime = true;
    for (int k = 2; k < dist / 2; ++k) {
        if (dist % k == 0) {
            prime = false;
            break;
        }
    }
    if (prime) {
        result += sentence.substr(i, dist);
    }
    if (result[result.length() - 1] == ' ') {
        result.pop_back();
    }
    return result;
}

