    long largest_divisor = n - 1;
    // Check each value up to n-1
    for (long i = largest_divisor; i > 0; i--) {
        // Check if n divided by i is even
        if (n % i == 0) {
            // This is the largest divisor
            largest_divisor = i;
            // Skip to the next value
            break;
        }
    }
    return largest_divisor;
}

