vector<int> get_odd_collatz(int n){
    std::vector<long> collatz = {1};
    std::set<long> set_collatz;
    set_collatz.insert(1);
    // if n is 1, we return [1]
    if (n == 1) {
        return collatz;
    }
    while (true) {
        // if n is odd, return 3*n+1
        if (n % 2 != 0) {
            n = 3*n + 1;
            // if n is odd and n exists in set, return
            if (set_collatz.find(n) != set_collatz.end()) {
                return collatz;
            }
            set_collatz.insert(n);
            collatz.push_back(n);
        }
        // if n is even, return n/2
        else {
            n = n/2;
            // if n is even and n exists in set, return
            if (set_collatz.find(n) != set_collatz.end()) {
                return collatz;
            }
            set_collatz.insert(n);
            collatz.push_back(n);
        }
    }
}

