        f1 += ')';
        f2 += ')';
    }
    std::stack<char> st;
    for(int i = 0; i < f1.length(); i++) {
        if(f1[i] == '(') {
            st.push(f1[i]);
        } else {
            if(st.empty()) {
                return "No";
            }
            st.pop();
        }
    }
    while(!st.empty()) {
        if(st.top() == '(') {
            st.pop();
