#include<stdlib.h>
bool is_multiply_prime(int a){
    long aCpy = a;
    std::vector<int> primeNumbers;
    int counter = 0;
    for (int i = 2; i < aCpy; i++) {
        for (int j = 2; j <= i; j++) {
            if (i % j == 0) {
                counter++;
            }
        }
        if (counter == 1) {
            primeNumbers.push_back(i);
        }
        counter = 0;
    }
    for (int k = 0; k < primeNumbers.size(); k++) {
        for (int l = k + 1; l < primeNumbers.size(); l++) {
            if (aCpy % (primeNumbers[k] * primeNumbers[l]) == 0) {
                aCpy = aCpy / (primeNumbers[k] * primeNumbers[l]);
                k = -1;
                l = 0;
            }
        }
    }
    if (aCpy == 1) {
        return true;
    }
    return false;
}

