#include<math.h>
using namespace std;
#include<algorithm>
#include<stdlib.h>
bool is_multiply_prime(int a){
    int k = 0;
    for (int i = 2; i <= a; i++) {
        if (a % i == 0) {
            for (int j = 2; j <= i; j++) {
                if (i % j == 0) {
                    k++;
                }
            }
            if (k == 1) {
                a /= i;
                k = 0;
            }
        }
    }
    if (a == 1) {
        return true;
    }
    return false;
}

