    int flag = 0;
    for (int i = 2; i <= a / 2; ++i) {
        if (a % i == 0) {
            if (i == 2) {
                continue;
            }
            for (int j = 2; j <= i / 2; ++j) {
                if (i % j == 0) {
                    flag = 1;
                    break;
                }
            }
            if (flag == 0) {
                if (a / i == 2) {
                    continue;
                }
                for (int k = 2; k <= a / i / 2; ++k) {
                    if (a / i % k == 0) {
                        flag = 1;
                        break;
                    }
                }
                if (flag == 0) {
                    for (int l = 2; l <= a / i / a * i; ++l) {
                        if (a / i / a * i % l == 0) {
                            flag = 1;
                            break;
                        }
                    }
                    if (flag == 0) {
                        return true;
                    }
                }
            }
        }
    }
    return false;
}

