bool is_multiply_prime(int a){
    assert(a>=1 && a<=1e18);
    std::vector<long> prime;
    for(long p=2; p*p<=a; p++) {
        if(a%p==0) {
            prime.push_back(p);
            while(a%p==0) a/=p;
        }
    }
    if(a>1) prime.push_back(a);
    return prime.size()==3;
}

