#include<math.h>
#include<string>
#include<algorithm>
using namespace std;
#include<stdlib.h>
string get_closest_vowel(string word){
    // Let's build the vowel string
    std::string vowel = "AEIOUaeiou";
    // Set a flag
    bool isVowel = false;
    // Set distance to maximum value.
    int distance = INT_MAX;
    // Loop through the word
    for (int i = 0; i < word.length(); i++) {
        // Check if the current character is a vowel
        if (vowel.find(word[i]) != std::string::npos) {
            // Loop through the consonants on right side of the vowel
            for (int j = i + 1; j < word.length(); j++) {
                // Break if we find a vowel
                if (vowel.find(word[j]) != std::string::npos) {
                    break;
                }
                // Check if the current distance is better than our initial distance
                if (j - i < distance) {
                    // Update our distance
                    distance = j - i;
                    // Update our isVowel flag
                    isVowel = true;
                }
            }
        }
    }
    // If no vowels were found, return empty string
    if (!isVowel) {
        return "";
    }
    // Return the closest vowel found.
    return word[distance - 1];
}

