    std::vector<std::pair<int, int>> v;

    for (auto i = 0; i < word.size(); i++) {
        for (auto j = 0; j < vowels.size(); j++) {
            if (word[i] == vowels[j]) {
                v.push_back(std::make_pair(i, j));
            }
        }
    }

