  for (int i = 1; i < size; i++) {
    // Check if the sum of the current sub-array is less than or equal to the
    // current element in the array
    if (curr_sum <= nums[i]) {
      // If the sum of the current sub-array is less than or equal to the current
      // element in the array, then set the sum of the current sub-array to the
      // current element in the array
      curr_sum = nums[i];
    } else {
      // If the sum of the current sub-array is greater than the current element
      // in the array, then add the current element in the array to the sum of
      // the current sub-array
      curr_sum += nums[i];
