int get_matrix_triples(int n){
    if(n==0)
        return 0;
    long ans = 0;
    for(long i=1;i<n;i++)
    {
        for(long j=i+1;j<n;j++)
        {
            long k = j+1;
            long sum = (k*k) - k + 1;
            long maxsum = sum;
            long times = 1;
            if(sum%3==0)
            {
                ans+=j-i;
                continue;
            }
            while(sum%3!=0)
            {
                k++;
                sum = (k*k) - k + 1;
                maxsum+=sum;
                times++;
            }
            while(maxsum%3!=0)
            {
                maxsum-=sum;
                k--;
                sum = (k*k) - k + 1;
                times--;
            }
            if(times>0)
                ans+=j-i;
        }
    }
    return ans;
}

