    std::stringstream ss(x);
  std::string token;
  int numer;
  int denom;
  int count = 0;
  while(std::getline(ss, token, '/')) {
    if (count == 0)
      numer = std::stoi(token);
    else if (count == 1)
      denom = std::stoi(token);
    count += 1;
  }
  // numer * denom/denom == numer
  if (numer * denom % denom == 0)
    return true;
  else
    return false;
}

