bool simplify(string x,string n){
    std::vector<std::string>v1,v2;
  std::string delimiter = "/";
  size_t pos = 0;
  std::string token;
  while ((pos = x.find(delimiter)) != std::string::npos) {
      token = x.substr(0, pos);
      v1.push_back(token);
      x.erase(0, pos + delimiter.length());
  }
  v1.push_back(x);
  while ((pos = n.find(delimiter)) != std::string::npos) {
      token = n.substr(0, pos);
      v2.push_back(token);
      n.erase(0, pos + delimiter.length());
  }
  v2.push_back(n);
  std::vector<int> f1,f2;
  for(int i=0;i<v1.size();i++){
    int h = std::stoi(v1[i]);
    f1.push_back(h);
  }
  for(int i=0;i<v2.size();i++){
    int h = std::stoi(v2[i]);
    f2.push_back(h);
  }
  int gcd = __gcd(f1[0]*f2[1],f1[1]*f2[0]);
  if(gcd == f1[1]*f2[0]){
    return true;
  }
  else{
    return false;
  }
}

