string remove_vowels(string text){
    std::string vowels = "aeiouAEIOU";
    int n = text.length();
    std::string textCopy = text;
    int i, j;
    for (i = 0; i < n; i++) {
        if (vowels.find(text[i]) != std::string::npos) {
            // if vowel is found, copy following characters to preceding
            for (j = i; j < n; j++) {
                textCopy[j] = textCopy[j + 1];
            }
            n -= 1;
            i -= 1;
        }
    }
    textCopy.resize(n);
    return textCopy;
}

