		interval2_set.insert(i);
	}
	std::set<long>::iterator it;
	for (it = interval1_set.begin(); it != interval1_set.end(); it++) {
		if (interval2_set.find(*it) != interval2_set.end()) {
			flag = true;
			prime_vec.push_back(*it);
		}
	}
	if (flag == false)
		return "NO";
	for (long i = 0; i < prime_vec.size(); i++) {
		counter_prime = 0;
		for (long j = 1; j <= prime_vec[i]; j++) {
			if (prime_vec[i] % j == 0)
				counter_prime++;
		}
		if (counter_prime == 2)
			count_prime++;
	}
	if (count_prime == 0)
		return "NO";
	return "YES";
