string intersection( vector<int> interval1,vector<int> interval2){
    int s1 = std::get<0>(interval1);
	int e1 = std::get<1>(interval1);
	int s2 = std::get<0>(interval2);
	int e2 = std::get<1>(interval2);
	// let's calculate the length of the intersection between the two intervals
	int length = 0;
	if (s1 <= s2 && e1 >= s2) {
		// intersection starts at s2
		if (e1 <= e2) {
			// intersection ends at e1
			length = e1 - s2 + 1;
		}
		else {
			// intersection ends at e2
			length = e2 - s2 + 1;
		}
	}
	else if (s2 <= s1 && e2 >= s1) {
		// intersection starts at s1
		if (e2 <= e1) {
			// intersection ends at e2
			length = e2 - s1 + 1;
		}
		else {
			// intersection ends at e1
			length = e1 - s1 + 1;
		}
	}
	else {
		// no intersection
		return "NO";
	}
	// now let's check if the length is a prime number
	if (length < 2) return "NO";
