int fib4(int n){
    // A better way to get the result is to use Array
// Array is faster than LinkedList
    long[] fib4 = new long[4];
    fib4[0] = 0;
    fib4[1] = 0;
    fib4[2] = 2;
    fib4[3] = 0;
    if (n < 4) {
        return fib4[n];
    }
    int i = 3;
    while (i < n) {
        fib4[0] = fib4[1];
        fib4[1] = fib4[2];
        fib4[2] = fib4[3];
        fib4[3] = fib4[0] + fib4[1] + fib4[2];
        i++;
    }
    return fib4[3];
}

