    if(paren_string.length() == 1) {
        v.push_back(paren_string);
        return v;
    }
    std::stack<int> s;
    int val = paren_string[0];
    if(val == '(') s.push(val);
    if(val == ')') s.pop();
    int start = 1;
    int end = 1;
    while(end < paren_string.length()) {
        if(s.empty()) {
            std::string sub = paren_string.substr(start, end - start);
            v.push_back(sub);
            start = end;
        }
        val = paren_string[end];
        if(val == '(') s.push(val);
        if(val == ')') s.pop();
        end++;
    }
    if(!s.empty()) {
        v.push_back(paren_string.substr(start, end - start));
    }
    return v;
}

