#include<stdio.h>
#include<math.h>
#include<vector>
#include<string>
using namespace std;
#include<algorithm>
#include<stdlib.h>
vector<int> even_odd_palindrome(int n){
    int even = 0, odd = 0;
    for (int i = 1; i <= n; i++) {
        std::string s = std::to_string(i);
        int len = s.length();
        bool isPalindrome = true;
        for (int j = 0; j < len / 2; j++) {
            if (s[j] != s[len - j - 1]) {
                isPalindrome = false;
                break;
            }
        }
        if (isPalindrome) {
            if (len % 2 == 0) {
                even++;
            } else {
                odd++;
            }
        }
    }
    return std::make_tuple(even, odd);
}

