    for (auto it = numbers.begin(); it != numbers.end(); ++it) {
        if (deque.empty()) {
            deque.push_back(*it);
            result.push_back(*it);
        } else {
            if (*it < deque.back()) {
                deque.push_back(*it);
                result.push_back(deque.front());
            } else {
                while (!deque.empty() && *it > deque.back()) {
                    deque.pop_back();
                }
                deque.push_back(*it);
                result.push_back(deque.front());
            }
        }
    }
    return result;
}

