int next_smallest(vector<int> lst){
    if (lst.size() <= 1) {
        return std::nullopt;
    }
    if (lst.size() == 2) {
        if (lst[0] == lst[1]) {
            return std::nullopt;
        }
    }
    auto min = std::min_element(lst.begin(), lst.end());
    int min_pos = std::distance(lst.begin(), min);
    lst.erase(lst.begin() + min_pos);
    auto temp = std::min_element(lst.begin(), lst.end());
    return *temp;
}

