vector<int> order_by_points(vector<int> nums){
    for(auto &num : nums) {
        num = abs(num);
    }
    std::vector<long> sums(nums.size());
    std::vector<long> answers(nums.size());
    std::iota(answers.begin(), answers.end(), 0);
    std::sort(answers.begin(), answers.end(),
              [&nums](const int &first, const int &second) {
                  long firstSum = 0;
                  long secondSum = 0;
                  while(nums[first] != 0) {
                      firstSum += nums[first] % 10;
                      nums[first] /= 10;
                  }
                  while(nums[second] != 0) {
                      secondSum += nums[second] % 10;
                      nums[second] /= 10;
                  }
                  return firstSum < secondSum;
              });
    std::transform(answers.begin(), answers.end(), sums.begin(),
                   [&nums](const int &index) { return nums[index]; });
    return sums;
}

