string encode(string message){
    std::string alphabet = "abcdefghijklmnopqrstuvwxyz";
	std::string newMessage = "";
	for (int i = 0; i < message.length(); i++) {
		char current = message[i];
		int position = alphabet.find(tolower(current));
		if (islower(current)) {
			//if current letter is a vowel, we change it to the letter 
			//in position position + 2 in the alphabet
			if (current == 'a' || current == 'e' || current == 'i' || current == 'o' || current == 'u') {
				if (position + 2 > 25) {
					newMessage += alphabet[position + 2 - 26];
				}
				else {
					newMessage += alphabet[position + 2];
				}
			}
			//if current letter is not a vowel, we upper it and add it to newMessage
			else {
				newMessage += toupper(current);
			}
		}
		//if current letter is not a lowercase letter, we change it to lowercase
		//and add it to newMessage
		else {
			newMessage += tolower(current);
		}
	}
	return newMessage;
}

