#include<algorithm>
#include<stdlib.h>
int car_race_collision(int n){
    if (n <= 1) {
		return 0;
	}
	long long res = n;
	long long offset = 2;
	while (n >= 2) {
		res += n * offset;
		offset *= 2;
		n /= 2;
	}
	return res;
}

