#include<stdio.h>
#include<math.h>
using namespace std;
#include<algorithm>
#include<stdlib.h>
int car_race_collision(int n){
    // Create a vector of the positions of the cars
  std::vector<long> right_to_left;
  std::vector<long> left_to_right;
  for (long i = 0; i < n; i++) {
    right_to_left.push_back(i);
    left_to_right.push_back(i);
  }
  // Now sort the two vectors.
  std::sort(right_to_left.begin(), right_to_left.end());
  std::sort(left_to_right.begin(), left_to_right.end());
  // Now traverse the two vectors and see how many collisions there are.
  long i = 0;
  long j = 0;
  long retval = 0;
  while (i < n && j < n) {
    if (right_to_left[i] == left_to_right[j]) {
      retval++;
      i++;
      j++;
    } else if (right_to_left[i] < left_to_right[j]) {
      i++;
    } else {
      j++;
    }
  }
  return retval;
}

