vector<int> largest_smallest_integers(vector<int> lst){
    if (lst.size() == 0) {
		return std::make_tuple(std::nullopt, std::nullopt);
	}
	long positive = INT_MAX;
	long negative = INT_MIN;
	for (long num : lst) {
		if (num > 0) {
			positive = std::min(positive, num);
		}
		else if (num < 0) {
			negative = std::max(negative, num);
		}
	}
	if (positive == INT_MAX) {
		positive = std::nullopt;
	}
	if (negative == INT_MIN) {
		negative = std::nullopt;
	}
	return std::make_tuple(negative, positive);
}

