using namespace std;
#include<algorithm>
#include<stdlib.h>
string circular_shift(int x,int shift){
    std::vector<long> digits;
	int n = x;
	int d;
	// create array with digits
	while (n >= 1) {
		d = n % 10;
		digits.push_back(d);
		n = n / 10;
	}
	// reverse the digits in the array
	int start = 0;
	int end = digits.size() - 1;
	int temp;
	while (start < end) {
		temp = digits[start];
		digits[start] = digits[end];
		digits[end] = temp;
		start++;
		end--;
	}
	// if shift is more than number of digits, return reversed digits
	if (shift > digits.size()) {
		std::string s = "";
		int i;
		for (i = 0; i < digits.size(); i++) {
			s += std::to_string(digits[i]);
		}
		return s;
	}
	// shift the digits
	int shiftValue = shift % digits.size();
	std::vector<long> finalDigits;
	for (int i = 0; i < digits.size(); i++) {
		finalDigits.push_back(digits[(i + shiftValue) % digits.size()]);
	}
	// if shift is 0, return reversed digits
	if (shift == 0) {
		std::string s = "";
		int i;
		for (i = 0; i < digits.size(); i++) {
			s += std::to_string(digits[i]);
		}
		return s;
	}
	// return shifted digits
	std::string s = "";
	int i;
	for (i = 0; i < finalDigits.size(); i++) {
		s += std::to_string(finalDigits[i]);
	}
	return s;
}

