using namespace std;
#include<algorithm>
#include<math.h>
#include<stdlib.h>
vector<int> parse_nested_parens(string paren_string){
    // Write your code here
    // Prepare a stack to be used to process the parenthsis.
    std::stack<char> s;
    // Prepare a vector to hold the output, where each element is the max count of
    // nesting of parenthesis encountered in each group.
    std::vector<long> output;
    // Iterate over each char in the input string, we are interested in only '(' and ')'
    for (int i = 0; i < paren_string.length(); i++) {
        // If '(' push the current count of maximum nesting into the stack.
        if (paren_string[i] == '(') {
            s.push(0);
        }
        // If ')' is found, calculate the new max count of nesting by adding 1 to
        // the maximum count of nesting in the current level.
        else if (paren_string[i] == ')') {
            long new_max = 1;
            while (!s.empty() && s.top() != 0) {
                new_max += s.top();
                s.pop();
            }
            // Now push the new max count of nesting of parenthesis in the current level.
            s.push(new_max);
        }
        // If ' ' is found, we know that a group of parenthesis has ended.
        // Pop all the elements from the stack and push them into the output.
        // While doing so, keep track of the max nesting of parenthesis in the
        // current group.
        else if (paren_string[i] == ' ') {
            long max_count = 0;
            while (!s.empty()) {
                max_count = std::max(max_count, s.top());
                s.pop();
            }
            output.push_back(max_count);
        }
    }
    return output;
}

