    for(int i = 0; i < operand.size() - 1; i++) {
        char op = _operator_[i][0];
        long op1 = stk.top();
        stk.pop();
        long op2 = operand[i + 1];
        switch(op) {
            case '+':
                stk.push(op1 + op2);
                break;
            case '-':
                stk.push(op1 - op2);
                break;
            case '*':
                stk.push(op1 * op2);
                break;
            case '/':
                stk.push(op1 / op2);
                break;
            case '^':
                stk.push(std::pow(op1, op2));
                break;
        }
    }
    return stk.top();
}

