#include<stdlib.h>
string filp_case(string str){
    // Create a stack to store the characters
std::stack<char> stk;
// Create a string to store the flipped string
std::string flippedString;

// Push every character of input string to stack
for(int i=0; i<string.length(); i++)
	stk.push(string[i]);

// Flip the case of string and store in new string
while(!stk.empty())
{
	if((stk.top()>='a') && (stk.top()<='z'))
		flippedString += (stk.top()-'a'+'A');
	else if((stk.top()>='A') && (stk.top()<='Z'))
		flippedString += (stk.top()-'A'+'a');
	else
		flippedString += stk.top();
	stk.pop();
}

