using namespace std;
#include<algorithm>
#include<math.h>
#include<stdlib.h>
bool is_palindrome(string str){
    string s(str.rbegin(),str.rend());
    return s==str;
}
string make_palindrome(string str){
    // Find the longest palindromic suffix
    auto const end = std::begin(string);
    auto const begin = std::prev(std::end(string));
    auto const last = std::end(string);
    for (auto it = begin; it != end; --it) {
        if (std::equal(it, last, std::begin(string))) {
            // Reverse of the prefix that comes before the palindromic suffix
            auto prefix_begin = std::next(it);
            auto prefix_end = last;
            while (prefix_begin != prefix_end) {
                std::iter_swap(prefix_begin, std::prev(prefix_end));
                ++prefix_begin;
                --prefix_end;
            }
            // Append the reverse of the prefix to the end of the string
            std::copy(std::next(it), last, std::back_inserter(string));
            return string;
        }
    }
    // The entire string is a palindrome, so we return the original string twice
    return string + string;
}

