string make_palindrome(string str){
    // Trivial case.
    if (string.empty()) {
        return string;
    }
    // Preprocessing.
    // Prefix function.
    std::vector<int> pi(string.size());
    pi[0] = 0;
    for (int i = 1; i < string.size(); ++i) {
        int j = pi[i - 1];
        while (j > 0 && string[i] != string[j]) {
            j = pi[j - 1];
        }
        if (string[i] == string[j]) {
            ++j;
        }
        pi[i] = j;
    }
    // Find the longest prefix of the reverse of the string that is also a suffix of the string.
    std::string reverse_string = string;
    std::reverse(reverse_string.begin(), reverse_string.end());
    int longest_prefix = pi[string.size() - 1];
    // Concatenate the right part of the prefix of the string and the reverse of the left part of the prefix of the string.
    // This forms a palindrome.
    return string + reverse_string.substr(longest_prefix);
}

