    int longest_palindrome_length = 0;
    // For each character index, find the longest palindrome beginning at that
    // index that is centered on that index.  Note that this loop begins at
    // index 1, since a string of length 1 is a palindrome.
    for (int center_index = 1; center_index < string.length(); center_index++) {
        // Find the palindrome centered on this character.
        // Note that this loop only iterates if a palindrome with an even
        // number of characters is found.
        for (int palindrome_length = 0; center_index - palindrome_length >= 0 && center_index + palindrome_length < string.length(); palindrome_length++) {
