bool is_palindrome(string str){
    string s(str.rbegin(),str.rend());
    return s==str;
}
string make_palindrome(string str){
    if (string.empty()) {
        return "";
    }
    int n = string.size();
    std::vector<std::vector<bool>> is_palindrome(n, std::vector<bool>(n, false));
    // Loop from the beginning to the end of the string.
    for (int i = 0; i < n; ++i) {
        // From the i-th character from the beginning to the beginning of the string.
        for (int j = 0; j <= i; ++j) {
            // If all the characters are the same.
            if (string[i] == string[j] && (i - j <= 2 || is_palindrome[i - 1][j + 1])) {
                is_palindrome[i][j] = true;
            }
        }
    }
    // Find the longest palindromic suffix.
    int max_j = 0;
    int max_i = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= i; ++j) {
            if (is_palindrome[i][j] && max_i - max_j < i - j) {
                max_i = i;
                max_j = j;
            }
        }
    }
    // Append the prefix and suffix.
    std::string result = string;
    for (int i = 0; i < max_j; ++i) {
        result += string[max_j - i - 1];
    }
    return result;
}

