	if (s.size() == 1) {
		char temp = s[0];
		if (isalpha(temp)) {
			if (isupper(temp)) {
				temp = tolower(temp);
			}
			else if (islower(temp)) {
				temp = toupper(temp);
			}
		}
		return std::string(1, temp);
	}
	else {
		// check if no letters
		bool check = true;
		for (size_t i = 0; i < s.size(); i++) {
			if (isalpha(s[i])) {
				check = false;
				break;
			}
		}
		if (check) {
			for (size_t i = s.size() - 1; i >= 0; i--) {
				result += s[i];
			}
			return result;
		}
		else {
			for (size_t i = 0; i < s.size(); i++) {
				char temp = s[i];
				if (isalpha(temp)) {
					if (isupper(temp)) {
						temp = tolower(temp);
					}
					else if (islower(temp)) {
						temp = toupper(temp);
					}
				}
				result += temp;
			}
			return result;
